from __future__ import annotations

BILLING_SCRIPT = 'const state={user:null,nodes:[],aiClients:[],billing:null};\nconst BILLING_PLAN_RANK={free:0,pro:1,pro_plus:2};\nlet billingSelectedInterval=\'month\';\nfunction billingSetInterval(interval){billingSelectedInterval=interval===\'year\'?\'year\':\'month\';const y=billingSelectedInterval===\'year\';const m=billingEl(\'billingCycleMonth\'),a=billingEl(\'billingCycleYear\');if(m){m.classList.toggle(\'primary\',!y);m.classList.toggle(\'secondary\',y)}if(a){a.classList.toggle(\'primary\',y);a.classList.toggle(\'secondary\',!y)}if(billingEl(\'billingProPrice\'))billingEl(\'billingProPrice\').textContent=y?\'$99.99\':\'$9.99\';if(billingEl(\'billingProPeriod\'))billingEl(\'billingProPeriod\').textContent=y?\'/ year\':\'/ month\';if(billingEl(\'billingProPlusPrice\'))billingEl(\'billingProPlusPrice\').textContent=y?\'$199.99\':\'$19.99\';if(billingEl(\'billingProPlusPeriod\'))billingEl(\'billingProPlusPeriod\').textContent=y?\'/ year\':\'/ month\';if(billingEl(\'billingExpansionPrice\'))billingEl(\'billingExpansionPrice\').textContent=y?\'$149.99/yr\':\'$14.99/mo\';if(state.billing)billingRefreshPlanButtons(state.billing)}\nfunction billingRefreshPlanButtons(s){for(const [plan,id] of [[\'free\',\'billingChooseFree\'],[\'pro\',\'billingChoosePro\'],[\'pro_plus\',\'billingChooseProPlus\']]){const cmp=BILLING_PLAN_RANK[plan]-BILLING_PLAN_RANK[s.plan];const sameInterval=plan===\'free\'||billingSelectedInterval===(s.billing_interval||\'month\');billingSetButton(id,cmp===0&&sameInterval?\'Current\':(cmp===0?\'Switch billing\':(cmp>0?\'Upgrade\':\'Downgrade\')),cmp===0&&sameInterval,cmp===0&&sameInterval?\'secondary\':\'primary\')}}\nfunction billingEl(id){return document.getElementById(id)}\nfunction billingSetButton(id,label,disabled,kind=\'primary\'){const b=billingEl(id);if(!b)return;b.textContent=label;b.disabled=disabled;b.classList.remove(\'primary\',\'secondary\');b.classList.add(kind)}\nfunction billingShowError(err){const box=billingEl(\'billingError\');if(!box)return;box.textContent=err?.message||String(err);box.classList.remove(\'hidden\')}\nfunction billingNotice(text,kind=\'info\'){const box=billingEl(\'billingNotice\');if(!box)return;box.textContent=text;box.classList.remove(\'hidden\');box.style.background=kind===\'success\'?\'#ecfdf3\':\'#eff4ff\';box.style.color=kind===\'success\'?\'#027a48\':\'#344054\'}\nasync function loadBillingView(){try{const error=billingEl(\'billingError\');if(error)error.classList.add(\'hidden\');const s=await api(\'/api/billing/summary\');state.billing=s;billingEl(\'billingPlan\').textContent=s.plan_name+(s.expansion_quantity?\' + \'+s.expansion_quantity+\' Pack\'+(s.expansion_quantity===1?\'\':\'s\'):\'\');billingEl(\'billingRenew\').textContent=s.renewal_at?\'Renews \'+new Date(s.renewal_at*1000).toLocaleDateString():\'\';billingEl(\'billingPrice\').textContent=s.plan===\'free\'?\'$0\':(s.billing_interval===\'year\'?\'$\'+Number(s.billing_total||0).toFixed(2)+\'/yr\':\'$\'+Number(s.billing_total||s.monthly_price||0).toFixed(2)+\'/mo\');billingEl(\'billingRequests\').textContent=Number(s.requests_used||0).toLocaleString()+\' / \'+Number(s.request_limit||0).toLocaleString();billingEl(\'billingComputers\').textContent=Number(s.nodes_used||0)+\' / \'+Number(s.node_limit||0)+(Number(s.nodes_connected||0)>Number(s.node_limit||0)?\' active · \'+Number(s.nodes_connected||0)+\' connected\':\'\');billingEl(\'billingAi\').textContent=Number(s.ai_accounts_used||0)+\' / \'+Number(s.ai_account_limit||0);const bar=billingEl(\'billingRequestsBar\')?.querySelector(\'i\');if(bar)bar.style.width=Math.min(100,Math.round((Number(s.requests_used||0)/Math.max(1,Number(s.request_limit||0)))*100))+\'%\';const cards={free:billingEl(\'billingCardFree\'),pro:billingEl(\'billingCardPro\'),pro_plus:billingEl(\'billingCardProPlus\')};Object.values(cards).forEach(x=>{if(x){x.style.outline=\'\';x.style.boxShadow=\'\'}});if(cards[s.plan]){cards[s.plan].style.outline=\'2px solid #84adff\';cards[s.plan].style.boxShadow=\'0 0 0 3px #d1e0ff\'};const requestedInterval=new URLSearchParams(location.search).get(\'interval\');billingSetInterval(requestedInterval===\'year\'?\'year\':(s.billing_interval||\'month\'));billingRefreshPlanButtons(s);const manage=billingEl(\'billingManage\');if(manage)manage.disabled=!s.has_customer;const expansion=billingEl(\'billingExpansion\');if(expansion)expansion.innerHTML=s.can_buy_expansion?\'<div class="toolbar" style="margin:0"><span class="muted">Current: \'+s.expansion_quantity+\'</span><input id="billingExpansionQty" class="input" type="number" min="1" max="100" value="1" style="width:80px"><button class="btn primary" onclick="billingAddExpansion()">Add Pack</button></div>\':\'<span class="muted">Available on Pro+</span>\';if(!s.billing_configured)billingNotice(\'Stripe checkout is not active yet. Your current plan and usage remain available here.\');else if(location.pathname===\'/billing/success\')billingNotice(\'Payment received. Your plan will update as soon as Stripe confirms the subscription.\',\'success\');else if(location.pathname===\'/billing/cancel\')billingNotice(\'Payment was not completed. Your current plan has not changed.\');const selected=new URLSearchParams(location.search).get(\'select\');if(selected&&(selected!==s.plan||billingSelectedInterval!==(s.billing_interval||\'month\'))){await billingChangePlan(selected)}}catch(err){billingShowError(err)}}\nasync function billingChangePlan(plan){try{const s=state.billing||await api(\'/api/billing/summary\');if(plan===s.plan&&billingSelectedInterval===(s.billing_interval||\'month\'))return;if(BILLING_PLAN_RANK[plan]<BILLING_PLAN_RANK[s.plan])return billingPortal();const d=await api(\'/api/billing/checkout\',{method:\'POST\',body:JSON.stringify({plan,interval:billingSelectedInterval})});if(d?.url)location=d.url}catch(err){billingShowError(err)}}\nasync function billingAddExpansion(){try{const input=billingEl(\'billingExpansionQty\');const quantity=Math.max(1,Number(input?.value||1));const d=await api(\'/api/billing/expansion\',{method:\'POST\',body:JSON.stringify({quantity})});if(d?.url)location=d.url}catch(err){billingShowError(err)}}\nasync function billingPortal(){try{const d=await api(\'/api/billing/portal\',{method:\'POST\'});if(d?.url)location=d.url}catch(err){billingShowError(err)}}\nwindow.billingSetInterval=billingSetInterval;window.loadBillingView=loadBillingView;window.billingChangePlan=billingChangePlan;window.billingAddExpansion=billingAddExpansion;window.billingPortal=billingPortal;\n'
